  Theorem cache_dealloc_sreach :
    (forall msF' mo', cache_dealloc_post L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c P CA R rbeg FAB TH TSD CTX sb ARI p cnt mc nf mfa au mu
